  questions: [
    {
      id: "note-flowering-plants-001", text: "A label places a specimen in Magnoliaceae. In this statement, what is Magnoliaceae?",
      options: [{ key: "a", text: "A rank called genus" }, { key: "b", text: "A taxon at family rank" }, { key: "c", text: "A rank called order" }, { key: "d", text: "A taxon at class rank" }],
      answer: "b", explanation: "Family is the rank, while Magnoliaceae is a particular named taxon occupying that rank. The -aceae ending is the conventional botanical family suffix in the source table.", sectionId: "taxonomy-systematics-and-ranks", source: { document: "biology", page: 255 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-002", text: "Which maize label corrects the handwritten binomial while retaining its author citation?",
      options: [{ key: "a", text: "<em>Zea mays</em> L." }, { key: "b", text: "<em>Zea Maize</em> L." }, { key: "c", text: "<em>zea Mays</em> L." }, { key: "d", text: "<em>Mays zea</em> L." }],
      answer: "a", explanation: "The correct binomial is Zea mays: Zea is the capitalized genus and mays the lowercase epithet. The author abbreviation L. remains outside the italicized binomial.", sectionId: "binomials-and-classification-systems", source: { document: "biology", page: 255 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-003", text: "Which historical system placed seed plants in Dicotyledones, Gymnospermae and Monocotyledones?",
      options: [{ key: "a", text: "Whittaker's five-kingdom system" }, { key: "b", text: "Linnaeus's 24-class sexual system" }, { key: "c", text: "Theophrastus's habit grouping" }, { key: "d", text: "Bentham and Hooker's natural system" }],
      answer: "d", explanation: "Bentham and Hooker arranged spermatophytes in those three classes. This is a historical natural classification, not evidence that modern gymnosperms are nested between two angiosperm lineages.", sectionId: "binomials-and-classification-systems", source: { document: "biology", page: 256 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-004", text: "A diagram labels the entire angiosperm ovule as a haploid female gametophyte. Which replacement is accurate?",
      options: [{ key: "a", text: "The integuments are the female gametophyte" }, { key: "b", text: "The ovary wall is the female gametophyte" }, { key: "c", text: "The embryo sac is the female gametophyte" }, { key: "d", text: "The nucellus alone is the female gametophyte" }],
      answer: "c", explanation: "The embryo sac is the reduced female gametophyte inside the ovule. The ovule also contains sporophytic tissues such as integuments and nucellus, so the whole structure cannot be labelled haploid gametophyte.", sectionId: "angiosperm-body-and-name-table", source: { document: "biology", page: 257 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-005", text: "Which corrected scientific name matches the source's sunn-hemp entry?",
      options: [{ key: "a", text: "Coriandrum sativum" }, { key: "b", text: "Cinnamomum camphora" }, { key: "c", text: "Anacardium occidentale" }, { key: "d", text: "Crotalaria juncea" }],
      answer: "d", explanation: "The plant-name table identifies sunn hemp as Crotalaria juncea. Coriandrum is coriander, Cinnamomum camphora the camphor tree, and Anacardium occidentale cashew.", sectionId: "angiosperm-body-and-name-table", source: { document: "biology", page: 257 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-006", text: "A new lateral root must pass through tissues outside its point of origin. Which origin explains this endogenous emergence?",
      options: [{ key: "a", text: "A single epidermal root-hair cell" }, { key: "b", text: "Cells in the internal pericycle" }, { key: "c", text: "A shoot's superficial leaf axil" }, { key: "d", text: "Cells in the external root mucilage" }],
      answer: "b", explanation: "Lateral roots normally initiate in the pericycle, inside the endodermis and cortex, and grow outward through those tissues. Root hairs instead arise as superficial epidermal outgrowths.", sectionId: "root-systems-and-growth-zones", source: { document: "biology", page: 258 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-007", text: "Marks placed on a young root separate most rapidly just behind the dividing apex. Which labelled region chiefly accounts for this increase in length?",
      options: [{ key: "a", text: "Region of elongation" }, { key: "b", text: "Mature lateral-root base" }, { key: "c", text: "External root-cap mucilage" }, { key: "d", text: "Fully differentiated root-hair tip" }],
      answer: "a", explanation: "New cells lengthen most strongly in the elongation region behind the meristem. The maturation region differentiates and forms root hairs; the source's contradictory maturation-only growth arrow is corrected.", sectionId: "root-systems-and-growth-zones", source: { document: "biology", page: 258 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-008", text: "Which description distinguishes a fusiform storage root from a conical one?",
      options: [{ key: "a", text: "A rounded upper body with an abrupt narrow tail" }, { key: "b", text: "A cluster of swollen roots arising together" }, { key: "c", text: "A central swelling tapering towards both ends" }, { key: "d", text: "A broad base tapering steadily towards one end" }],
      answer: "c", explanation: "A fusiform root, illustrated by radish, is swollen in the middle and narrows at both ends. Carrot is conical, while the rounded upper storage body with a slender lower region is the napiform comparison.", sectionId: "storage-support-and-symbiotic-roots", source: { document: "quick-revision", page: 124 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-009", text: "A root in mango ginger is swollen mainly near its tip. Which source term fits this pattern?",
      options: [{ key: "a", text: "Fasciculated" }, { key: "b", text: "Napiform" }, { key: "c", text: "Nodulose" }, { key: "d", text: "Conical" }],
      answer: "c", explanation: "Curcuma amada, mango ginger, is the source's nodulose-root example: swelling is concentrated near the tip. Fasciculated refers to a cluster of swollen roots, not a single tip-localized swelling.", sectionId: "storage-support-and-symbiotic-roots", source: { document: "quick-revision", page: 123 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-010", text: "Why is 'leghaemoglobin makes a nodule completely oxygen-free' an inadequate explanation?",
      options: [{ key: "a", text: "It replaces all bacterial nitrogenase activity" }, { key: "b", text: "It raises free oxygen to atmospheric levels" }, { key: "c", text: "It converts the nodule into a photosynthetic leaf" }, { key: "d", text: "It buffers free oxygen while respiration continues" }],
      answer: "d", explanation: "Leghaemoglobin maintains a low free-oxygen environment that protects nitrogen fixation while allowing the oxygen supply needed for respiration. Microaerobic does not mean that all oxygen and aerobic metabolism disappear.", sectionId: "storage-support-and-symbiotic-roots", source: { document: "quick-revision", page: 123 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-011", text: "Which tissue is highlighted in the hanging absorptive roots of Vanda?",
      options: [{ key: "a", text: "Pappus" }, { key: "b", text: "Velamen" }, { key: "c", text: "Replum" }, { key: "d", text: "Pulvinus" }],
      answer: "b", explanation: "Vanda is an epiphytic orchid with velamen in its aerial absorptive roots. Pappus belongs to floral calyx modifications, replum to mustard fruits, and pulvinus to a swollen leaf base.", sectionId: "aerial-parasitic-and-respiratory-roots", source: { document: "biology", page: 258 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-012", text: "A palm has an unbranched trunk with its crown near the top. Which stem-form term matches the coconut example?",
      options: [{ key: "a", text: "Caudex" }, { key: "b", text: "Culm" }, { key: "c", text: "Rhizome" }, { key: "d", text: "Stolon" }],
      answer: "a", explanation: "The source uses caudex for the unbranched palm-like coconut trunk. Culm refers to a grass stem such as bamboo, while rhizomes and stolons are spreading shoot modifications.", sectionId: "stem-habit-buds-and-functions", source: { document: "biology", page: 259 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-013", text: "An underground storage organ bears scale-leaf scars with eyes capable of making shoots. Which interpretation fits these observations?",
      options: [{ key: "a", text: "A stem tuber with nodal bud complexes" }, { key: "b", text: "A tap root with epidermal root hairs" }, { key: "c", text: "A root nodule with bacterial chambers" }, { key: "d", text: "A seed with multiple micropyles" }],
      answer: "a", explanation: "Nodes, scale-leaf scars and axillary bud complexes establish stem identity in a potato tuber. They distinguish it from a storage root such as sweet potato and correct the source's adventitious-eye label.", sectionId: "subaerial-and-underground-stems", source: { document: "biology", page: 259 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-014", text: "Two green, leaf-like organs have different origins: one is an Acacia petiole and the other a short Ruscus branch. What are they, respectively?",
      options: [{ key: "a", text: "Cladode and phyllode" }, { key: "b", text: "Phylloclade and stipule" }, { key: "c", text: "Phyllode and cladode" }, { key: "d", text: "Stipule and phylloclade" }],
      answer: "c", explanation: "A flattened photosynthetic leaf petiole is a phyllode, while a short photosynthetic branch such as Ruscus is a cladode. Similar shape and function do not imply the same organ of origin.", sectionId: "photosynthetic-stems-thorns-and-bulbils", source: { document: "quick-revision", page: 124 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-015", text: "Which pair is explicitly linked to the source's BAD bulbil mnemonic?",
      options: [{ key: "a", text: "Cynodon and Hydrocotyle" }, { key: "b", text: "Citrus and Duranta" }, { key: "c", text: "Asparagus and Ruscus" }, { key: "d", text: "Agave and Dioscorea" }],
      answer: "d", explanation: "BAD expands to bulbil, Agave and Dioscorea. A bulbil is a bud-derived vegetative propagule, whereas the other pairs illustrate runners, thorns or photosynthetic short shoots.", sectionId: "photosynthetic-stems-thorns-and-bulbils", source: { document: "quick-revision", page: 124 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-016", text: "A daughter Pistia rosette remains attached to its parent by a short, one-internode branch. Which propagation structure is present?",
      options: [{ key: "a", text: "A long woody liana" }, { key: "b", text: "A short offset" }, { key: "c", text: "A vertical corm" }, { key: "d", text: "A root-borne thorn" }],
      answer: "b", explanation: "Offsets are short runner-like branches that establish daughter rosettes, as illustrated for Pistia and Eichhornia. A corm is a swollen underground stem, not the short connector between two rosettes.", sectionId: "subaerial-and-underground-stems", source: { document: "biology", page: 259 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-017", text: "What is the main storage distinction between an onion bulb and a Colocasia corm?",
      options: [{ key: "a", text: "Bulb: root cortex; corm: seed cotyledons" }, { key: "b", text: "Bulb: swollen stem; corm: fleshy leaves" }, { key: "c", text: "Bulb: seed cotyledons; corm: root cortex" }, { key: "d", text: "Bulb: fleshy leaves; corm: swollen stem" }],
      answer: "d", explanation: "An onion bulb has a reduced basal stem with fleshy storage leaves. A Colocasia corm stores mainly in its short, swollen stem, although it also bears scale leaves and buds.", sectionId: "subaerial-and-underground-stems", source: { document: "biology", page: 259 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-018", text: "In the compound-leaf diagram, which structure carries the leaflets beyond the petiole?",
      options: [{ key: "a", text: "Rachis" }, { key: "b", text: "Root cap" }, { key: "c", text: "Replum" }, { key: "d", text: "Spathe" }],
      answer: "a", explanation: "The rachis is the axis carrying leaflets in a pinnately compound leaf. The midrib of a simple lamina should not automatically be renamed rachis merely because both occupy central positions.", sectionId: "leaf-blades-venation-and-arrangement", source: { document: "biology", page: 260 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-019", text: "A Polygonum specimen has stipules united into a sheath around its stem. Which stipule category is this?",
      options: [{ key: "a", text: "Adnate" }, { key: "b", text: "Foliaceous" }, { key: "c", text: "Ochreate" }, { key: "d", text: "Tendrillar" }],
      answer: "c", explanation: "Ochreate stipules form an ochrea, a sheath around the stem, as in Polygonum. Adnate stipules join the petiole, and foliaceous or tendrillar stipules have different shapes and roles.", sectionId: "leaf-parts-petioles-and-stipules", source: { document: "quick-revision", page: 126 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-020", text: "Which change most directly produces rapid movement in a Mimosa pulvinus?",
      options: [{ key: "a", text: "Permanent lignification of all motor cells" }, { key: "b", text: "Ion-linked redistribution of water and turgor" }, { key: "c", text: "Meiosis of the swollen leaf-base cells" }, { key: "d", text: "Conversion of the petiole into an anther" }],
      answer: "b", explanation: "Pulvinar movements involve ion redistribution, including potassium, and resulting water and turgor changes in motor cells. Merely storing potassium without changing its distribution does not explain the movement.", sectionId: "leaf-parts-petioles-and-stipules", source: { document: "quick-revision", page: 126 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-021", text: "Two leaves arise at each node, and each successive pair is rotated by a right angle. Which phyllotaxy is illustrated?",
      options: [{ key: "a", text: "Alternate spiral" }, { key: "b", text: "Opposite decussate" }, { key: "c", text: "Opposite superposed" }, { key: "d", text: "Three-leaved whorled" }],
      answer: "b", explanation: "Opposite decussate phyllotaxy has paired leaves with successive pairs in perpendicular planes, as in the source's Ocimum and Calotropis examples. Superposed pairs instead remain in the same plane.", sectionId: "leaf-blades-venation-and-arrangement", source: { document: "biology", page: 261 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-022", text: "Which observation is called ptyxis in the printed leaf comparison?",
      options: [{ key: "a", text: "A young leaf's folding relative to itself" }, { key: "b", text: "Mature leaves positioned along a branch" }, { key: "c", text: "Veinlets joining within an expanded blade" }, { key: "d", text: "Petals overlapping within a flower bud" }],
      answer: "a", explanation: "Ptyxis is the folding of one young leaf relative to itself, exemplified by a coiled fern leaf. Phyllotaxy describes mature leaf arrangement, venation vein pattern and aestivation floral-bud overlap.", sectionId: "leaf-blades-venation-and-arrangement", source: { document: "quick-revision", page: 125 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-023", text: "Which specimen would disprove the claim that every monocot leaf has parallel venation?",
      options: [{ key: "a", text: "A wheat blade with longitudinal veins" }, { key: "b", text: "A ginger blade with one main midrib" }, { key: "c", text: "A maize blade with parallel side veins" }, { key: "d", text: "A Smilax blade with a vein network" }],
      answer: "d", explanation: "Smilax is one of the SAD monocot exceptions with reticulate venation, alongside Alocasia and Dioscorea. A vein network therefore does not alone establish dicot identity.", sectionId: "leaf-blades-venation-and-arrangement", source: { document: "quick-revision", page: 125 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-024", text: "Which plant has the whole-leaf tendril correctly identified in the printed source?",
      options: [{ key: "a", text: "Pisum sativum" }, { key: "b", text: "Gloriosa superba" }, { key: "c", text: "Lathyrus aphaca" }, { key: "d", text: "Passiflora species" }],
      answer: "c", explanation: "Lathyrus aphaca is the whole-leaf tendril example. Pisum modifies leaflets, Gloriosa the leaf tip, and Passiflora an axillary shoot; these origins should remain distinct despite their climbing role.", sectionId: "tendrils-spines-and-insectivorous-leaves", source: { document: "quick-revision", page: 125 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-025", text: "A sharp rose outgrowth detaches with superficial tissues and lacks the organization of a shoot. Which term fits it?",
      options: [{ key: "a", text: "Axillary thorn" }, { key: "b", text: "Stipular spine" }, { key: "c", text: "Root thorn" }, { key: "d", text: "Superficial prickle" }],
      answer: "d", explanation: "Rose prickles are superficial epidermal/cortical emergences, unlike vascularized stem thorns or leaf-derived spines. Calling them modified axillary buds, as one source line does, changes their organ identity.", sectionId: "tendrils-spines-and-insectivorous-leaves", source: { document: "biology", page: 261 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-026", text: "Which source-listed leaf modification collects water/debris without being an insectivorous pitcher?",
      options: [{ key: "a", text: "Drosera's sticky tentacles" }, { key: "b", text: "Dischidia's pitcher-like leaf" }, { key: "c", text: "Utricularia's bladder trap" }, { key: "d", text: "Nepenthes's pitfall pitcher" }],
      answer: "b", explanation: "The source explicitly distinguishes Dischidia's lidless, non-insectivorous pitcher-like leaves from carnivorous leaf traps. A pitcher-like shape alone does not establish carnivory.", sectionId: "tendrils-spines-and-insectivorous-leaves", source: { document: "quick-revision", page: 126 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-027", text: "An inflorescence has sessile flowers along an elongated axis instead of the pedicellate flowers of a raceme. Which form is it?",
      options: [{ key: "a", text: "Spike" }, { key: "b", text: "Corymb" }, { key: "c", text: "Umbel" }, { key: "d", text: "Cyathium" }],
      answer: "a", explanation: "A spike resembles a raceme but its flowers are sessile. A corymb changes pedicel lengths, an umbel has a common origin for rays, and a cyathium is a specialized reduced-flower complex.", sectionId: "inflorescence-types-and-development", source: { document: "quick-revision", page: 127 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-028", text: "Flowers arise at different heights, but longer lower pedicels produce an approximately level top. Which candytuft pattern is described?",
      options: [{ key: "a", text: "A pendulous catkin" }, { key: "b", text: "A fleshy spadix" }, { key: "c", text: "A corymb" }, { key: "d", text: "A hypanthodium" }],
      answer: "c", explanation: "The corymb brings flowers to a similar level by unequal pedicel lengths arising at different positions. This distinguishes it from an umbel, where the primary rays arise from a common region.", sectionId: "inflorescence-types-and-development", source: { document: "quick-revision", page: 127 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-029", text: "One central reduced female flower and many reduced male flowers occur inside an involucre in Euphorbia. What is the unit?",
      options: [{ key: "a", text: "A verticillaster" }, { key: "b", text: "A compound umbel" }, { key: "c", text: "A cyathium" }, { key: "d", text: "A hypanthodium" }],
      answer: "c", explanation: "A cyathium contains the characteristic central female flower and surrounding reduced male flowers. The whole flower-like structure is an inflorescence, not one bisexual flower with ordinary petal whorls.", sectionId: "inflorescence-types-and-development", source: { document: "quick-revision", page: 127 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-030", text: "A student's flower has a superior ovary enclosed by, but not fused to, a hypanthium. Other whorls arise at its rim. Which interpretation is appropriate?",
      options: [{ key: "a", text: "Epigyny proves the ovary is inferior" }, { key: "b", text: "Hypogyny requires a fused inferior ovary" }, { key: "c", text: "Perigyny requires a half-inferior ovary" }, { key: "d", text: "Perigyny can retain a superior ovary" }],
      answer: "d", explanation: "Perigyny describes whorl insertion on a cup around the gynoecium. When the hypanthium is not adnate to the ovary, the ovary remains superior; half-superior is not an obligatory consequence.", sectionId: "flower-sex-symmetry-and-ovary-position", source: { document: "quick-revision", page: 128 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-031", text: "Which floral-axis elongation lies between the androecium and gynoecium in the source's three-part comparison?",
      options: [{ key: "a", text: "Anthophore" }, { key: "b", text: "Gynophore" }, { key: "c", text: "Androphore" }, { key: "d", text: "Rhizophore" }],
      answer: "b", explanation: "The gynophore is the stalk-like region below the gynoecium, described in the source between stamens and carpels. Anthophore and androphore refer to lower floral-axis regions in the same comparison.", sectionId: "flower-sex-symmetry-and-ovary-position", source: { document: "quick-revision", page: 129 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-032", text: "A gynoecium has three fused carpels but only one mature chamber. Which conclusion follows?",
      options: [{ key: "a", text: "Carpel number need not equal locule number" }, { key: "b", text: "A single chamber proves only one carpel" }, { key: "c", text: "Fused carpels require three separate pistils" }, { key: "d", text: "One chamber excludes a syncarpous gynoecium" }],
      answer: "a", explanation: "Carpel number describes the contributing floral units, while locule number describes internal chambers. Loss or absence of septa can leave a multicarpellary syncarpous ovary unilocular.", sectionId: "carpels-locules-and-placentation", source: { document: "biology", page: 263 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-033", text: "Ovules surround a central column, but no septa connect that column to the ovary wall. Which placentation matches the drawing?",
      options: [{ key: "a", text: "Free central" }, { key: "b", text: "Parietal" }, { key: "c", text: "Marginal" }, { key: "d", text: "Axile" }],
      answer: "a", explanation: "Free-central placentation has a central ovule-bearing column without septa reaching the wall. Axile placentation instead accompanies septa meeting at a central axis in a multilocular ovary.", sectionId: "carpels-locules-and-placentation", source: { document: "biology", page: 263 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-034", text: "Which pairing correctly describes two contrasting types of stamen union?",
      options: [{ key: "a", text: "Monadelphous: anthers united; syngenesious: filaments united" }, { key: "b", text: "Monadelphous: both parts united; syngenesious: neither united" }, { key: "c", text: "Monadelphous: filaments united; syngenesious: anthers united" }, { key: "d", text: "Monadelphous: neither united; syngenesious: both parts united" }],
      answer: "c", explanation: "Monadelphous stamens have one united filament bundle with free anthers. Syngenesious stamens have united anthers and free filaments. Fusion of both parts is not the definition of either condition.", sectionId: "androecium-aestivation-and-formula-key", source: { document: "biology", page: 263 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-035", text: "In a papilionaceous corolla, the standard overlaps the wings, which overlap the keel. Which aestivation is shown?",
      options: [{ key: "a", text: "Valvate" }, { key: "b", text: "Ascending imbricate" }, { key: "c", text: "Twisted" }, { key: "d", text: "Vexillary" }],
      answer: "d", explanation: "Vexillary, or descending imbricate, aestivation has the standard outside the wings and the wings outside the keel. It is the checked papilionoid pattern rather than the ascending caesalpinioid comparison.", sectionId: "androecium-aestivation-and-formula-key", source: { document: "biology", page: 268 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-036", text: "Six stamens are present: two short outer stamens and four long inner stamens. Which term describes the mustard arrangement?",
      options: [{ key: "a", text: "Didynamous" }, { key: "b", text: "Tetradynamous" }, { key: "c", text: "Diadelphous" }, { key: "d", text: "Syngenesious" }],
      answer: "b", explanation: "Tetradynamous refers to four long and two short stamens, the mustard pattern. It does not mean merely four stamens or a multiple of four, and it describes relative lengths rather than fusion.", sectionId: "brassicaceae-family", source: { document: "quick-revision", page: 121 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-037", text: "A Brassica ovary gains a false partition during development. Which original feature remains compatible with its apparently two-chambered mature state?",
      options: [{ key: "a", text: "A single free carpel with a basal ovule" }, { key: "b", text: "Three free carpels with superficial ovules" }, { key: "c", text: "One fused carpel with no placental tissue" }, { key: "d", text: "Two fused carpels with parietal placentation" }],
      answer: "d", explanation: "Brassica is bicarpellary and syncarpous with parietal placentation. The secondary partition does not change its carpel origin into an axile, three-carpel or single-carpel organization.", sectionId: "brassicaceae-family", source: { document: "biology", page: 267 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-038", text: "Which corrected diagnosis replaces the source's 'only two fertile stamens' statement for a representative Solanaceae flower?",
      options: [{ key: "a", text: "Five stamens attached to the corolla" }, { key: "b", text: "Six stamens in a tetradynamous set" }, { key: "c", text: "Numerous stamens in one filament tube" }, { key: "d", text: "Nine united stamens with one free" }],
      answer: "a", explanation: "A representative Solanaceae flower has five epipetalous stamens. The other diagnoses belong to the mustard, mallow and pea-type comparisons and do not repair the source's mistaken two-fertile-stamen claim.", sectionId: "solanaceae-family", source: { document: "biology", page: 267 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-039", text: "Which fruit pair matches the source's Solanaceae examples?",
      options: [{ key: "a", text: "Tomato: capsule; Datura: cypsela" }, { key: "b", text: "Tomato: drupe; Datura: legume" }, { key: "c", text: "Tomato: berry; Datura: capsule" }, { key: "d", text: "Tomato: pome; Datura: siliqua" }],
      answer: "c", explanation: "Tomato and brinjal are berry examples in Solanaceae, while Datura produces a capsule. Pomes, siliquae, legumes and cypselas refer to different fruit organizations.", sectionId: "solanaceae-family", source: { document: "biology", page: 267 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-040", text: "Which feature separates the traditional caesalpinioid flower comparison from the pea-type papilionoid one?",
      options: [{ key: "a", text: "A caryopsis instead of a carpel-derived fruit" }, { key: "b", text: "Ascending rather than vexillary corolla overlap" }, { key: "c", text: "An inferior rather than an enclosed ovary" }, { key: "d", text: "A pappus instead of any calyx structure" }],
      answer: "b", explanation: "The traditional table contrasts ascending imbricate caesalpinioid corollas with descending imbricate, vexillary papilionoid corollas. Both groups are legumes; neither caryopsis nor pappus defines this distinction.", sectionId: "fabaceae-family-and-subfamilies", source: { document: "quick-revision", page: 121 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-041", text: "Which name correctly identifies Sisau after separating two conflated printed entries?",
      options: [{ key: "a", text: "Desmodium gyrans" }, { key: "b", text: "Dalbergia sissoo" }, { key: "c", text: "Cajanus cajan" }, { key: "d", text: "Butea monosperma" }],
      answer: "b", explanation: "Sisau or shisham is Dalbergia sissoo. Desmodium gyrans is the telegraph-plant entry, Cajanus cajan pigeon pea and Butea monosperma flame of the forest.", sectionId: "fabaceae-family-and-subfamilies", source: { document: "quick-revision", page: 121 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-042", text: "Which feature distinguishes a grass caryopsis from a sunflower cypsela?",
      options: [{ key: "a", text: "Fusion of pericarp to the seed coat" }, { key: "b", text: "Development from an inferior ovary" }, { key: "c", text: "Opening into two detached valves" }, { key: "d", text: "Formation from many separate flowers" }],
      answer: "a", explanation: "A caryopsis has the pericarp fused to the seed coat. A cypsela develops from an inferior ovary and does not have seed-coat fusion as its defining feature; both are dry indehiscent fruits.", sectionId: "fruits-pericarp-and-simple-types", source: { document: "quick-revision", page: 122 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-043", text: "One flower produces many free ovaries, each becoming a raspberry drupelet. How should the whole fruit be classified?",
      options: [{ key: "a", text: "Multiple fruit from an inflorescence" }, { key: "b", text: "Simple capsule from one ovary" }, { key: "c", text: "Syconium from a hollow receptacle" }, { key: "d", text: "Aggregate fruit from one flower" }],
      answer: "d", explanation: "The many drupelets come from separate ovaries of a single flower, so raspberry is aggregate. A multiple fruit combines products of several flowers; many visible units alone do not establish that origin.", sectionId: "aggregate-multiple-fruits-and-seed-labels", source: { document: "biology", page: 264 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-044", text: "Which correction removes the pineapple entry from the source's sunflower-family diagnosis?",
      options: [{ key: "a", text: "Pineapple is a Solanum berry in Solanaceae" }, { key: "b", text: "Pineapple is a Magnolia achene in Magnoliaceae" }, { key: "c", text: "Pineapple is Ananas in Bromeliaceae" }, { key: "d", text: "Pineapple is Allium in the onion group" }],
      answer: "c", explanation: "Pineapple is Ananas, family Bromeliaceae. The handwritten pairing with Chrysanthemum is wrong; its multiple sorosis fruit cannot be made a characteristic Asteraceae cypsela by that placement.", sectionId: "asteraceae-family-and-florets", source: { document: "biology", page: 268 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-045", text: "What is the calyx-derived dispersal structure described by the source's parachute comparison?",
      options: [{ key: "a", text: "A grass palea" }, { key: "b", text: "A mallow epicalyx" }, { key: "c", text: "A mustard replum" }, { key: "d", text: "An asteraceous pappus" }],
      answer: "d", explanation: "A pappus is a modified calyx, often with hairs or bristles that aid dispersal in Asteraceae. It is not the grass perianth; grasses have lodicules rather than the pappus copied into the source's grass column.", sectionId: "asteraceae-family-and-florets", source: { document: "quick-revision", page: 129 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-046", text: "Which combination best matches the source's Hibiscus-type Malvaceae flower?",
      options: [{ key: "a", text: "Dithecous anthers with nine-plus-one filaments" }, { key: "b", text: "Monothecous anthers with a staminal column" }, { key: "c", text: "Dithecous anthers with four long and two short stamens" }, { key: "d", text: "United anthers with five separate filaments" }],
      answer: "b", explanation: "The mallow example has numerous monadelphous stamens forming a filament column and monothecous, kidney-shaped anthers. The other combinations describe pea, mustard or Asteraceae patterns.", sectionId: "malvaceae-and-cucurbitaceae-families", source: { document: "biology", page: 269 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-047", text: "A female cucurbit flower has an inferior ovary and later forms a pepo. Which placentation is expected in the source account?",
      options: [{ key: "a", text: "Parietal, often with intrusive placentae" }, { key: "b", text: "Marginal along one free carpel" }, { key: "c", text: "Free central without any wall association" }, { key: "d", text: "Basal with the single grass ovule" }],
      answer: "a", explanation: "Cucurbitaceae has parietal placentation, often with strongly inward-growing placentae that complicate the internal appearance. Its inferior ovary and pepo do not imply the grass's single basal ovule.", sectionId: "malvaceae-and-cucurbitaceae-families", source: { document: "biology", page: 269 }, cognitive: "understanding"
    },
    {
      id: "note-flowering-plants-048", text: "A lily has six tepals and six stamens attached to those tepals. Which term describes the attachment?",
      options: [{ key: "a", text: "Syngenesious" }, { key: "b", text: "Diadelphous" }, { key: "c", text: "Epiphyllous" }, { key: "d", text: "Tetradynamous" }],
      answer: "c", explanation: "Epiphyllous or epitepalous stamens attach to perianth segments. Syngenesious and diadelphous describe union among stamens, while tetradynamous describes the mustard stamen-length pattern.", sectionId: "lily-and-grass-family-comparison", source: { document: "biology", page: 269 }, cognitive: "recall"
    },
    {
      id: "note-flowering-plants-049", text: "A grass-flower label says 'pappus and three ovary chambers'. Which replacement gives the checked structures?",
      options: [{ key: "a", text: "Epicalyx and five ovary chambers" }, { key: "b", text: "Lodicules and one ovary chamber" }, { key: "c", text: "Replum and two ovary chambers" }, { key: "d", text: "Pappus and many free carpels" }],
      answer: "b", explanation: "The grass perianth is reduced to lodicules, and the mature ovary is unilocular with one basal ovule. Pappus belongs to Asteraceae; the copied pappus and trilocular claims in the source are corrected explicitly.", sectionId: "lily-and-grass-family-comparison", source: { document: "biology", page: 269 }, cognitive: "application"
    },
    {
      id: "note-flowering-plants-050", text: "A potometer records increased water uptake after a leafy shoot is exposed to moving air. What is the most defensible interpretation?",
      options: [{ key: "a", text: "Uptake is an approximate proxy for transpiration" }, { key: "b", text: "The instrument directly measures every stomatal pore" }, { key: "c", text: "Uptake directly counts the shoot's new cells" }, { key: "d", text: "The instrument measures only atmospheric humidity" }],
      answer: "a", explanation: "A potometer measures water uptake, which often approximates transpiration under suitable conditions. Some water enters storage or metabolism, so uptake should not be called a direct measurement of vapour loss.", sectionId: "assigned-water-relations-and-instruments", source: { document: "quick-revision", page: 129 }, cognitive: "application"
    }
  ]
